const scienceVariablesPurposeAt = (index) => index < 4 ? 'PROBE' : index < 16 ? 'PRACTICE' : index < 24 ? 'TRANSFER' : index < 30 ? 'LOCK_IN' : 'REVIEW';

const buildQuestions = (definition) => casesFor[definition.key].flatMap((item, caseIndex) => Array.from({ length: 4 }, (_, variant) => {
  const index = caseIndex * 4 + variant;
  const [label, context, question, directAnswer, criterion, transfer, limit, d1, d2, d3] = item;
  const prompts = [
    `${context}. ${question}`,
    `${context}. Que critério deve orientar a análise?`,
    `${context}. Como transferir esse raciocínio para outro contexto?`,
    `${context}. Qual conclusão deve ser evitada sem informação adicional?`,
  ];
  const answers = [directAnswer, criterion, transfer, limit];
  return makeQuestion({
    prefix: definition.prefix,
    index,
    contextFamily: `${definition.key}_${label.replaceAll(' ', '_').toUpperCase()}`,
    statement: prompts[variant],
    correctAnswer: answers[variant],
    distractors: [d1, d2, d3],
    explanation: definition.explanation,
    hint: definition.hint,
    misconception: definition.misconception,
    purposeAtFn: definition.purposeAtFn,
  });
}));

