      progression: PURPOSES.map((purpose) => ({ stage: stageFor[purpose], focus: ({ PROBE: 'Identificar ideia, critério ou variável central.', PRACTICE: 'Aplicar o procedimento em situações variadas.', TRANSFER: 'Avaliar limites e transferir para novo contexto.', LOCK_IN: 'Consolidar o raciocínio e reparar erros comuns.', REVIEW: 'Revisar evidência, estratégia e comunicação.' })[purpose], questionIds: questions.filter((question) => question.purpose === purpose).map((question) => question.id) })),
